{"command":"cd /tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/code-safety-base/.code-safety/NodeGoat-base-d/repo/program-4b9874c397f12ea5608efab69ddec460cfc94c863c0226b995797a6fcef8e672/@integration && cat > /tmp/build_union.mjs << 'EOF'
import { readFileSync, writeFileSync, readdirSync } from 'node:fs';
const dir = 'findings';
const dropped = new Set([
  'data-001',
  'platform-004',
  'platform-007',
  'platform-008',
  'platform-010',
  'secrets-hardcoded-session-cookie-secret',
]);
const all = [];
const byDept = {};
for (const entry of readdirSync(dir).sort()) {
  if (!entry.endsWith('.json')) continue;
  const dept = entry.replace('.json','');
  const arr = JSON.parse(readFileSync(`${dir}/${entry}`, 'utf8'));
  byDept[dept] = arr;
  for (const f of arr) all.push(f);
}
// check dedup groups
const keyMap = new Map();
for (const f of all) {
  const key = `${f.file}:${f.line}:${f.cwe}`;
  if (!keyMap.has(key)) keyMap.set(key, []);
  keyMap.get(key).push(f.id);
}
console.log('=== duplicate groups (file:line:cwe with >1 id) ===');
for (const [k, ids] of keyMap) {
  if (ids.length > 1) console.log(k, ids);
}
const kept = all.filter(f => !dropped.has(f.id));
console.log('total all:', all.length, 'kept:', kept.length, 'dropped:', all.length - kept.length);
// verify dropped set actually all existed
for (const id of dropped) {
  if (!all.some(f => f.id === id)) console.log('WARNING: dropped id not found in any dept file:', id);
}
// severity counts
const sev = {critical:0,high:0,medium:0,low:0,info:0};
for (const f of kept) sev[f.severity]++;
console.log('severity counts:', sev);
writeFileSync('findings.json.tmp', JSON.stringify(kept, null, 2) + '\n');
console.log('wrote findings.json.tmp with', kept.length, 'entries');
EOF
node /tmp/build_union.mjs","description":"Build union findings.json programmatically and verify dedup counts"}

