import { readFileSync } from 'node:fs';
const kept = JSON.parse(readFileSync('findings.json', 'utf8'));
const order = ['critical','high','medium','low','info'];
let out = '';
for (const sev of order) {
  const items = kept.filter(f => f.severity === sev);
  if (items.length === 0) continue;
  out += `### ${sev}\n\n`;
  for (const f of items) {
    const loc = f.endLine ? `${f.file}:${f.line}-${f.endLine}` : `${f.file}:${f.line}`;
    // trim impact/fix to keep reasonable length but keep full meaning-ish; keep as-is
    out += `- \`${f.id}\` — ${f.title} (\`${f.file}:${f.line}\`, ${f.cwe}, ${f.confidence}) — ${f.impact} Fix: ${f.fix}\n`;
  }
  out += '\n';
}
console.log(out);
EOF
