import { readFileSync, existsSync } from 'node:fs';
const target = JSON.parse(readFileSync('target.json','utf8'));
const root = target.root;
const files = new Set(Object.keys(target.files));
function resolves(path, line) {
  if (!files.has(path)) return false;
  const full = readFileSync(root + '/' + path, 'utf8').split('\n');
  return Number.isInteger(line) && line >= 1 && line <= full.length;
}
const text = readFileSync(process.argv[2], 'utf8');
for (const [m, path, line] of text.matchAll(/(?<![\w/.\-])([\w.-]+(?:\/[\w.-]+)*\.\w+):(\d+)\b/g)) {
  const ok = resolves(path, Number(line));
  if (!ok) console.log('BAD CITATION:', JSON.stringify(m), '->', path, line);
}
console.log('done');
EOF
